-- GENERATED by `wfj generate` from data/gossip/gossip-fb.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["fb01e5fba334dd9a"] = { "Ehi, ehi, ferma, Dadanga, bella mia.", "." },
  ["fb1436ac0b8e7493"] = { "Ah, sì, ora ricordo: era la tua prima notte di nozze, vero?", "." },
  ["fb183fa7e8d479e5"] = { "I Gordunni sono una grande tribù di ogre che controlla vaste porzioni delle foreste di Feralas. La loro magia oscura penetra negli elementi che li circondano, danneggiando sia l'ambiente sia le creature che lo abitano.\n\nSe decidi di andare a Feralas, ti prego, fai attenzione a questi ogre: sono davvero cattivi, e molti sanno usare una potente magia oscura.", "." },
  ["fb218eaa7e4b2240"] = { "Al tuo tocco, la macchina si anima.", "." },
  ["fb250a736cbf6607"] = { "Ecco qui, {name}.", "." },
  ["fb273d278a2d9e68"] = { "Situati lungo la ⟦Zoram Strand=Spiaggia di Zoram⟧, in ⟦Ashenvale=Valtetra⟧, gli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧ erano un tempo un tempio glorioso dedicato a Elune, la dea della luna degli elfi della notte. Ma la Grande Separazione frantumò il tempio, facendolo sprofondare sotto le onde del Mar Velato. Lì rimase intatto, finché, attirati dal suo antico potere, i naga e i satiri emersero per scoprirne i segreti. Le leggende dicono che l'antica bestia Aku'mai si sia stabilita fra le rovine del tempio.", "." },
  ["fb2929a5bc19ae93"] = { "Vattene subito, <straniero/straniera>! Non ho niente da spartire con te.", "." },
  ["fb2b536dc57f1708"] = { "%s salmodia in una lingua sconosciuta.", "." },
  ["fb2c08c54fd147f2"] = { "Che tu sia <benedetto/benedetta>, <confratello/sorella>. La nostra Sisterhood of Elune è un pilastro della società kaldorei da migliaia di anni.\n\nPrima della Grande Separazione, prima della Guerra degli Antichi, durante la Lunga Veglia, abbiamo guidato e curato il nostro popolo attraverso le tenebre. Tale è il nostro compito, e tale è ciò che esige l'impareggiabile Madre Luna.\n\nOra ci serve il tuo aiuto in una questione di grande importanza. La sorella Aquinne attende il tuo arrivo a Darnassus.", "." },
  ["fb2e3412d3cbf187"] = { "Vele all'orizzonte orientale. Invasori, senza dubbio! Fuoco!", "." },
  ["fb2ebf0feeb112f1"] = { "Il meglio dev'essere stata la faccia di Perenolde quando il nostro esercito è arrivato marciando fino alla sua porta. Che battaglia!", "." },
  ["fb32a29728bd6b55"] = { "Sta' attent<o/a> a dove metti i piedi da queste parti, <figliolo/ragazza>. Non farai parte della nostra squadra, ma questo non vuol dire che non ti prenda a bastonate se non righi dritto!", "." },
  ["fb366ed66c7d1df6"] = { "Hakkar non mi vincola più! Finalmente la pace!", "." },
  ["fb3f50efc7c7e9a9"] = { "Segugio all'orizzonte, si muove a trenta piedi al secondo. L'unica domanda è: occhio destro o sinistro? Proprio così, <ragazzo/ragazza>, ho una mira infallibile.", "." },
  ["fb513acd63589748"] = { "È gentile da parte tua chiederlo, {class}, ma abbiamo già tutto il Salmone Impanato che ci servirà per la guerra. Forse potresti chiedere agli altri raccoglitori qui: di sicuro avranno qualcosa in cui il tuo aiuto può servire.", "." },
  ["fb52c47ce12aba33"] = { "Ho perso un frammento dell'⟦Lord Valthalak's Amulet=Amuleto di Sire Valthalak⟧!", "." },
  ["fb6cb65e34b664ed"] = { "Il nostro popolo crede che nulla vada sprecato. Quando siamo costretti a uccidere una creatura, prendiamo ciò che possiamo perché il suo sacrificio non sia stato vano.\n\nSe vuoi imparare il modo giusto di scuoiare una bestia uccisa, cerca Eladriel nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧.", "." },
  ["fb70539fecdfa3b6"] = { "Era ora. Avevo fame già un'ora fa.", "." },
  ["fb71e752003f5645"] = { "Avventure da terre vicine e lontane\n\nincontri con genti bizzarre e strane\n\nma se una domanda mi vuoi fare\n\nprima un semplice compito devi completare!", "." },
  ["fb74c862027cfe18"] = { "Non ne posso più *ansima ansima*", "." },
  ["fb77df1ea00811b2"] = { "Oh, no! Abbiamo finito il tempo.", "." },
  ["fb7c06d353b2b603"] = { "Och! Questa sì che è un'arte che vale la pena conoscere. Tognus batte l'incudine con una furia che non si vede spesso. Perché non vai a parlargli e vedi cosa può insegnarti?", "." },
  ["fb7e33b6896e789c"] = { "<Questo {race} che giace davanti a te ha perso i sensi.>", "." },
  ["fb80cc507ab6e6da"] = { "Fammi vedere che liquori hai da vendere, Kreeg.", "." },
  ["fb82c5fb2542d324"] = { "Jeztor è vivo! È ora di illuminare il cielo della Valle, comandante.", "." },
  ["fb86896cdf3e4181"] = { "Mi spiace, Huldar... ma a quanto pare ti ho ingannato.", "." },
  ["fb88d4920ab49491"] = { "Lo tengo qui finché non ci serve...", "." },
  ["fb8cbcc075e2402f"] = { "Preparati a morire, feccia di paladino!", "." },
  ["fb92a3c78b695dc0"] = { "Bisogna fare attenzione ad accendere i fuochi d'artificio quando non ti senti più le dita...", "." },
  ["fb9339964c7d0716"] = { "Torni a finire il lavoro? <Lathoric ride.> Obsidion, sorgi e annientali!", "." },
  ["fba22d76e48a3352"] = { "PER L'ORDA!", "." },
  ["fba9094af6a975cf"] = { "%s lancia un'occhiata ai suoi compagni.", "." },
  ["fba95ffc7072f9f9"] = { "Ce l'abbiamo fatta, siamo a ⟦Nethergarde=Guardiafatua⟧!", "." },
  ["fbb042cca711eb1f"] = { "Finalmente! Fuori da questa cella, finalmente!\n\nIl Kirin Tor mi ha mandato da Dalaran a indagare sui progressi di Arugal con i non morti qui nella ⟦Silverpine Forest=Selva Pinargento⟧. Non sapevamo certo che il mago avesse perso la ragione.\n\nDevo riferire subito di questo pasticcio! Ma prima di andare, lascia che annulli il sigillo magico sulla porta del cortile.\n\nHai sconfitto ⟦Rethilgore=Sanguenero⟧, forse sopravvivrai a ciò che si trova là oltre....", "." },
  ["fbb0ab5d4a12e3c5"] = { "Da dove cominciare? La nostra casa sta cedendo. Le protezioni sono cadute e le tre province hanno cominciato ad allontanarsi l'una dall'altra. Non molto tempo fa, le guglie di Shen'dramar si vedevano dalla torre di guardia occidentale. Ora non più. I piloni d'ancoraggio si stanno indebolendo, e se le catene alla fine si spezzano...", "." },
  ["fbb39f8c4dcfbc51"] = { "La volontà di %s vacilla.", "." },
  ["fbb8c8248fae8fc9"] = { "Finalmente ci siamo, grazie a te, {name}! Senza il tuo aiuto saremmo finiti in pasto a qualche lucertolone troppo cresciuto!", "." },
  ["fbc7f3f35fe1b7fa"] = { "Ah! Tirth lo cerca da giorni, ma lui non vuole farsi trovare. È un fifone!", "." },
  ["fbce3b462d3726bb"] = { "I barili sono pieni di birra forte! Bevi, amico, e festeggia!", "." },
  ["fbd66ee318b84446"] = { "Osi toccarmi?!", "." },
  ["fbd730f4a08aa87b"] = { "Ti schiaccerò!", "." },
  ["fbe92b7ebd9933a5"] = { "Tutte le nostre raccolte sono completate, {class}. Ciò che abbiamo riunito è in viaggio verso la ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e il resto non dovrebbe metterci più di $2113w giorni ad arrivare. A quel punto potrà iniziare la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧, non appena qualcuno di coraggioso e sconsiderato suonerà il gong proprio fuori dai cancelli laggiù.", "." },
  ["fbf11a330733f673"] = { "Non posso credere che le nostre vite siano praticamente perdute per colpa di uno stupido medaglione! E sei sicur<o/a> che Anthion abbia parlato di Bodley?\n\nBe', hai fatto il tuo lavoro, quindi sbrighiamo la faccenda della tua ricompensa.", "." },
  ["fbf61df45afcd861"] = { "Non riesco proprio a sentirmi a mio agio senza un bel soffitto di granito sopra la testa. Tutte queste stelle lassù, c'è da farsi venire i brividi.", "." },
  ["fbfd46688195b090"] = { "Per me una pinta di birra ⟦Dark Iron=Ferroscuro⟧. Oh, non sei <il/la> <cameriere/cameriera>?", "." },
})
